CREATE INDEX `mobile_jobs_cleanup_idx` ON `mobile_jobs` (`expires_at`) WHERE "mobile_jobs"."state" IN ('done','failed') AND "mobile_jobs"."result" IS NOT NULL;--> statement-breakpoint
